import re
from abc import ABCMeta, abstractmethod
from six import add_metaclass
from moler.exceptions import CommandFailure  # type: ignore
from moler.util.moler_test import MolerTest  # type: ignore
from taf.ul.sc.perf.util.logger import log_debug_function_info
from taf.ul.sc.perf.collectors.benchmark_stats import BenchmarkStats
from taf.ul.sc.perf.collectors.dsp_stats import DspStats


@add_metaclass(ABCMeta)
class GenericBts(object):
    def __init__(self, bts, workstation=None, api=None, ems=None, syslog=None):

        self.bts = bts
        self.ws = workstation
        self.api = api
        self.ems = ems
        self.syslog = syslog

    @property
    @abstractmethod
    def name(self):
        pass

    @log_debug_function_info()
    def collect_info(self):
        version = self.get_version()
        bts_info = {'sw_version': version,
                    'sw_release': self.get_release_version_based_on_build(build=version),
                    'configuration': self.get_configuration()}
        return bts_info

    def start_observers(self):
        pass

    def stop_observers(self):
        pass

    def prepare(self):
        # full prepare bts like - upgrade, comissioning - could be keep in separate file
        pass

    @abstractmethod
    def get_version(self):
        pass

    @staticmethod
    def get_release_version_based_on_build(build):
        regex = re.compile(r'^(?P<RELEASE>.*?)_')
        match = regex.search(build)
        sw_release = match.group('RELEASE')

        return sw_release

    def waiting_for_site_response(self, rerun=60):
        MolerTest.sleep(5)
        self.bts.waiting_for_site_response(rerun=rerun)

    def get_configuration(self):
        # get number of cells etc.
        return 0

    def clear_and_backup_pm_files(self):
        self.ems.ws.create_pm_backup_directory()
        self.ems.ws.backup_pm_files()

    def get_bts_hardware_product_code(self):
        return self.bts.hardware_product_code

    def get_modules(self):
        return self.bts.get_modules()

    @log_debug_function_info()
    def collect_pm_files(self, log_dir, log_level='warning'):
        try:
            self.ems.ws.collect_pm_files(destination_dir=log_dir)
        except CommandFailure as e:
            if r'ERROR: zip error: Nothing to do!' in str(e):
                logger = getattr(MolerTest, log_level)
                logger(msg="PM files does not exists on EMS server.")

    @log_debug_function_info()
    def collect_rise_pm_data(self, log_dir):
        self.ems.ws.collect_rise_pm_data(destination_dir=log_dir)

    def get_bts_cells_info(self):
        bts_info = self.ems.cli.get_bts_info()
        cells_info = {'nr_of_cells': len(bts_info['cell_properties'].keys()), 'cells_bandwidths': [], 'cells_id': []}
        for cell in bts_info['cell_properties']:
            cells_info['cells_bandwidths'].append(bts_info['cell_properties'][cell]['downlink_tx_channel_bandwidth'])
            cells_info['cells_id'].append(bts_info['cell_properties'][cell]['global_cell_id'])
        cells_info['cells_bandwidths'] = ', '.join(set(cells_info['cells_bandwidths']))
        return cells_info

    @log_debug_function_info()
    def wait_for_onair_via_ems(self, timeout=900):
        self.ems.cli.discover()
        operational_state = self.ems.cli.get_operational_state()
        MolerTest.info(msg="Operation state of BTS is {}".format(operational_state))
        if operational_state != 'onAir':
            MolerTest.info(msg="BTS is not onAir - waiting {} seconds for onAir".format(operational_state))
            self.ems.cli.wait_for_onair(timeout=timeout)

    @log_debug_function_info()
    def change_swconfig(self, swconfig_file=None, swconfig_md5sum=None, remove_swconfig=False):
        set_new_swconfig = True
        new_configuration_applied = False

        swconfig_exists = self.bts.check_if_swconfig_exists()
        if remove_swconfig and swconfig_exists:
            self.bts.remove_swconfig()
            new_configuration_applied = True
        else:
            if swconfig_exists:
                bts_md5sum = self.bts.get_swcocnfig_md5sum()
                if swconfig_md5sum == bts_md5sum:
                    MolerTest.info(msg="swconfig files are the same.")
                    set_new_swconfig = False

            if set_new_swconfig:
                self.bts.set_swconfig(sw_config_path=swconfig_file)
                new_configuration_applied = True

        return new_configuration_applied

    def _collect_swconfig(self, log_dir):
        if self.bts.check_if_swconfig_exists():
            self.bts.get_swconfig(local_dir=log_dir)

    def _start_benchmark_stats_collecting(self, device, period=None):
        benchmark_stats = BenchmarkStats(device=device)
        benchmark_stats.scp_script_to_device()
        benchmark_stats.start_collecting(period=period)

    def _stop_benchmark_stats_collecting(self, device):
        benchmark_stats = BenchmarkStats(device=device)
        benchmark_stats.stop_collecting()
        benchmark_stats.copy_stats()

    def _start_dsp_stats_collecting(self, workstation, dsp_script, script_params):
        dsp_stats = DspStats(workstation=workstation, dsp_script=dsp_script, script_params=script_params)
        dsp_stats.scp_script_to_device()
        dsp_stats.start_dsp_collecting()

    def _stop_dsp_stats_collecting(self, workstation, dsp_script, script_params):
        dsp_stats = DspStats(workstation=workstation, dsp_script=dsp_script, script_params=script_params)
        dsp_stats.stop_dsp_collecting()

    def start_waiting_for_bts_stats(self, stats_type='rtpm', till_occurs_times=1):
        """
        Starts waiting for bts stats(rtpm or pmstats).

        :param stats_type: 'rtpm' or 'pmstats'
        :param till_occurs_times: number of event occurrence
        :return: event object - then you can use:
                 event.await_done(timeout=timeout) for waiting when event finish
        """
        if stats_type == 'rtpm':
            event = self.ems.cli.get_rtpm_stats_event(till_occurs_times=till_occurs_times)
        else:
            event = self.ems.cli.get_pm_stats_event(till_occurs_times=till_occurs_times)

        event.start()

        return event
